def copy_identity_from_user(apps, schema_editor):
    """Recopie nom, prénom et email du compte vers la fiche enseignant."""
    Teacher = apps.get_model("administration", "Teacher")
    for teacher in Teacher.objects.select_related("user").all():
        user = teacher.user
        if user is None:
            continue
        teacher.first_name = user.first_name or ""
        teacher.last_name = user.last_name or ""
        teacher.email = user.email or ""
        teacher.save(update_fields=["first_name", "last_name", "email"])


def detach_auto_created_accounts(apps, schema_editor):
    """Retire les comptes créés automatiquement pour les enseignants.

    Ces comptes (identifiant « ens_<matricule> ») n'avaient pas de mot de
    passe utilisable ni de rôle attribué : ils ne servaient pas à se
    connecter mais encombraient la liste des utilisateurs. Un compte qui a
    reçu un mot de passe, un rôle ou des droits d'administration est conservé
    et reste rattaché à sa fiche.
    """
    Teacher = apps.get_model("administration", "Teacher")
    User = apps.get_model("administration", "User")
    UserRoleAssignment = apps.get_model("administration", "UserRoleAssignment")
    for teacher in Teacher.objects.exclude(user__isnull=True).select_related("user"):
        user = teacher.user
        auto_created = (
            user.username.startswith("ens_")
            and (not user.password or user.password.startswith("!"))
            and not user.is_superuser
            and not user.is_admin
            and not user.is_secretary
            and not UserRoleAssignment.objects.filter(user_id=user.id).exists()
        )
        if not auto_created:
            continue
        teacher.user = None
        teacher.save(update_fields=["user"])
        User.objects.filter(pk=user.pk).delete()


